<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/auth.php'; requireAdmin();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['ticket_id'],$_POST['status'])) db_updateSupportStatus((int)$_POST['ticket_id'],$_POST['status']);
$filter=$_GET['status']??''; if(!in_array($filter,['open','answered','closed'],true)) $filter=''; $tickets=db_getSupportTickets($filter);
$labels=['open'=>'باز','answered'=>'پاسخ داده شده','closed'=>'بسته']; $badges=['open'=>'badge-pending','answered'=>'badge-confirmed','closed'=>'badge-cancelled'];
$adminTitle='پشتیبانی'; $adminActive='support'; include __DIR__.'/layout.php'; ?>
<div class="admin-header"><h1>درخواست‌های پشتیبانی</h1><div class="admin-filters"><a class="filter-btn <?= $filter===''?'active':'' ?>" href="support.php">همه</a><a class="filter-btn <?= $filter==='open'?'active':'' ?>" href="?status=open">باز</a><a class="filter-btn <?= $filter==='answered'?'active':'' ?>" href="?status=answered">پاسخ داده شده</a><a class="filter-btn <?= $filter==='closed'?'active':'' ?>" href="?status=closed">بسته</a></div></div>
<div class="support-admin-list"><?php if(!$tickets): ?><div class="empty-state">درخواستی ثبت نشده است.</div><?php else: foreach($tickets as $t): ?><article class="ticket-card"><div class="ticket-head"><div><span class="badge <?= $badges[$t['status']] ?>"><?= $labels[$t['status']] ?></span><h3>#<?= $t['id'] ?> — <?= htmlspecialchars($t['subject']) ?></h3><small><?= htmlspecialchars($t['name']) ?> · <?= htmlspecialchars($t['phone']) ?> · <?= date('Y/m/d H:i',strtotime($t['created_at'])) ?></small></div><form method="post" class="ticket-status"><input type="hidden" name="ticket_id" value="<?= $t['id'] ?>"><select name="status" class="status-select"><option value="open" <?= $t['status']==='open'?'selected':'' ?>>باز</option><option value="answered" <?= $t['status']==='answered'?'selected':'' ?>>پاسخ داده شده</option><option value="closed" <?= $t['status']==='closed'?'selected':'' ?>>بسته</option></select><button class="btn sm" type="submit">ذخیره</button></form></div><div class="ticket-message"><?= nl2br(htmlspecialchars($t['message'])) ?></div></article><?php endforeach; endif; ?></div></main></div></body></html>
